ALTER TABLE public.products
  ADD COLUMN IF NOT EXISTS product_type public.product_type DEFAULT 'plan_30',
  ADD COLUMN IF NOT EXISTS min_price DECIMAL(12,2),
  ADD COLUMN IF NOT EXISTS max_price DECIMAL(12,2),
  ADD COLUMN IF NOT EXISTS is_price_range BOOLEAN DEFAULT FALSE,
  ADD COLUMN IF NOT EXISTS creator_coach_id UUID REFERENCES public.coaches(id),
  ADD COLUMN IF NOT EXISTS creator_commission_percentage DECIMAL(5,2) DEFAULT 0,
  ADD COLUMN IF NOT EXISTS nutritionist_fee DECIMAL(12,2) DEFAULT 0,
  ADD COLUMN IF NOT EXISTS master_coach_commission DECIMAL(5,2) DEFAULT 10,
  ADD COLUMN IF NOT EXISTS room_rental_commission DECIMAL(5,2) DEFAULT 50,
  ADD COLUMN IF NOT EXISTS course_level INTEGER DEFAULT 1,
  ADD COLUMN IF NOT EXISTS course_target VARCHAR(50) DEFAULT 'all',
  ADD COLUMN IF NOT EXISTS profit_percentage_min DECIMAL(5,2) DEFAULT 0,
  ADD COLUMN IF NOT EXISTS profit_percentage_max DECIMAL(5,2) DEFAULT 0,
  ADD COLUMN IF NOT EXISTS subtitle VARCHAR(255),
  ADD COLUMN IF NOT EXISTS highlights JSONB DEFAULT '[]'::jsonb,
  ADD COLUMN IF NOT EXISTS is_featured BOOLEAN DEFAULT FALSE,
  ADD COLUMN IF NOT EXISTS badge_label VARCHAR(50),
  ADD COLUMN IF NOT EXISTS badge_color VARCHAR(20) DEFAULT '#F97316';
ALTER TABLE public.products ALTER COLUMN price DROP NOT NULL;
UPDATE public.products SET status = 'inactive' WHERE slug IS NULL OR slug NOT IN ('inscricao-fitmind','inscricao-premium-fitmind','plano-essencial-30','plano-intermediario-30','plano-avancado-30','plano-black-30','protocolo-transformacao-90','protocolo-elite-90','protocolo-master-90','protocolo-black-90','locacao-sala-fitmind','aulao-fitmind');
UPDATE public.digital_products SET status = 'inactive';
UPDATE public.store_products SET status = 'inactive';
DELETE FROM public.challenge_awards_config;

