('room_rental','physical','Locação de Sala FitMind Center','locacao-sala-fitmind','Espaço profissional para suas consultas e aulas','Alugue uma sala equipada no FitMind Center para atender clientes, dar aulas ou realizar workshops.',NULL,NULL,0,2.99,1.69,1.00,6.00,1,0,0,0,0,0,0,50,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,'["Salas equipadas e climatizadas","Recepção inclusa","Wi-Fi de alta velocidade","Estacionamento","Agendamento pelo app","Coach indicador recebe 50% do 1º aluguel"]',FALSE,'FitMind Center','#0EA5E9','active',30),
('live_class','challenge','Aulão FitMind','aulao-fitmind','Eventos ao vivo com fins lucrativos','Aulões organizados pelos coaches com comissão configurável por evento.',0,1,10,2.99,1.69,1.00,6.00,1,0,0,0,0,0,0,50,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,'["Evento ao vivo presencial ou online","Ingresso com QR Code no app","Lista de participantes automática","Comissão definida por evento","Certificado de participação digital"]',FALSE,'Aulão','#EC4899','active',40)
