CREATE TABLE IF NOT EXISTS public.master_coaches (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),coach_id UUID REFERENCES public.coaches(id) NOT NULL UNIQUE,specialty VARCHAR(100),crm_cref VARCHAR(50),bio TEXT,available_for_clients BOOLEAN DEFAULT TRUE,master_commission_percentage DECIMAL(5,2) DEFAULT 10.00,approved_at TIMESTAMPTZ,approved_by UUID REFERENCES public.profiles(id),status VARCHAR(20) DEFAULT 'pending',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.master_coach_attendances (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),master_coach_id UUID REFERENCES public.master_coaches(id) NOT NULL,student_id UUID REFERENCES public.students(id) NOT NULL,original_coach_id UUID REFERENCES public.coaches(id) NOT NULL,attendance_date DATE NOT NULL DEFAULT CURRENT_DATE,notes TEXT,resulted_in_sale BOOLEAN DEFAULT FALSE,transaction_id UUID REFERENCES public.transactions(id),commission_amount DECIMAL(12,2) DEFAULT 0,commission_status public.commission_status DEFAULT 'pending',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.room_rentals (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),renter_profile_id UUID REFERENCES public.profiles(id) NOT NULL,referring_coach_id UUID REFERENCES public.coaches(id),room_name VARCHAR(100),rental_date DATE NOT NULL,start_time TIME,end_time TIME,duration_hours DECIMAL(4,2),price_per_hour DECIMAL(8,2),total_amount DECIMAL(12,2),is_first_rental BOOLEAN DEFAULT FALSE,referral_commission_paid BOOLEAN DEFAULT FALSE,referral_commission_amount DECIMAL(12,2) DEFAULT 0,status VARCHAR(20) DEFAULT 'pending',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.live_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),product_id UUID REFERENCES public.products(id) NOT NULL,organizer_coach_id UUID REFERENCES public.coaches(id) NOT NULL,title VARCHAR(255) NOT NULL,description TEXT,cover_url TEXT,event_date TIMESTAMPTZ NOT NULL,location VARCHAR(255),is_online BOOLEAN DEFAULT FALSE,online_link TEXT,max_participants INTEGER,ticket_price DECIMAL(12,2) NOT NULL,organizer_commission_percentage DECIMAL(5,2) DEFAULT 60.00,platform_fee_percentage DECIMAL(5,2) DEFAULT 20.00,mlm_pool_percentage DECIMAL(5,2) DEFAULT 20.00,status VARCHAR(20) DEFAULT 'upcoming',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.event_tickets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),event_id UUID REFERENCES public.live_events(id) NOT NULL,student_id UUID REFERENCES public.students(id),profile_id UUID REFERENCES public.profiles(id) NOT NULL,referring_coach_id UUID REFERENCES public.coaches(id),ticket_code VARCHAR(20) UNIQUE,qr_code_url TEXT,amount_paid DECIMAL(12,2),payment_method public.payment_method,status VARCHAR(20) DEFAULT 'active',checked_in_at TIMESTAMPTZ,purchased_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.coach_created_courses (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),digital_product_id UUID REFERENCES public.digital_products(id) NOT NULL,creator_coach_id UUID REFERENCES public.coaches(id) NOT NULL,creator_commission_percentage DECIMAL(5,2) NOT NULL,upline_commission_percentage DECIMAL(5,2) DEFAULT 0,platform_percentage DECIMAL(5,2) DEFAULT 20.00,approved_by_admin BOOLEAN DEFAULT FALSE,approved_at TIMESTAMPTZ,status VARCHAR(20) DEFAULT 'pending_approval',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.course_teacher_commissions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),digital_product_id UUID REFERENCES public.digital_products(id) NOT NULL,teacher_profile_id UUID REFERENCES public.profiles(id) NOT NULL,commission_percentage DECIMAL(5,2) NOT NULL,is_active BOOLEAN DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT NOW());
ALTER TABLE public.commissions ADD COLUMN IF NOT EXISTS is_master_coach_commission BOOLEAN DEFAULT FALSE;
ALTER TABLE public.commissions ADD COLUMN IF NOT EXISTS master_coach_id UUID REFERENCES public.master_coaches(id);

ALTER TABLE public.master_coaches ENABLE ROW LEVEL SECURITY; ALTER TABLE public.master_coach_attendances ENABLE ROW LEVEL SECURITY; ALTER TABLE public.room_rentals ENABLE ROW LEVEL SECURITY; ALTER TABLE public.live_events ENABLE ROW LEVEL SECURITY; ALTER TABLE public.event_tickets ENABLE ROW LEVEL SECURITY; ALTER TABLE public.coach_created_courses ENABLE ROW LEVEL SECURITY; ALTER TABLE public.course_teacher_commissions ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS master_coaches_admin_all ON public.master_coaches; CREATE POLICY master_coaches_admin_all ON public.master_coaches FOR ALL USING (public.is_admin(auth.uid())) WITH CHECK (public.is_admin(auth.uid()));
DROP POLICY IF EXISTS master_coaches_read_active ON public.master_coaches; CREATE POLICY master_coaches_read_active ON public.master_coaches FOR SELECT USING (status = 'active');
DROP POLICY IF EXISTS master_attendances_admin_all ON public.master_coach_attendances; CREATE POLICY master_attendances_admin_all ON public.master_coach_attendances FOR ALL USING (public.is_admin(auth.uid())) WITH CHECK (public.is_admin(auth.uid()));
DROP POLICY IF EXISTS room_rentals_admin_all ON public.room_rentals; CREATE POLICY room_rentals_admin_all ON public.room_rentals FOR ALL USING (public.is_admin(auth.uid())) WITH CHECK (public.is_admin(auth.uid()));
DROP POLICY IF EXISTS room_rentals_own_read ON public.room_rentals; CREATE POLICY room_rentals_own_read ON public.room_rentals FOR SELECT USING (renter_profile_id IN (SELECT id FROM public.profiles WHERE user_id = auth.uid()) OR EXISTS (SELECT 1 FROM public.coaches c JOIN public.profiles p ON p.id=c.profile_id WHERE p.user_id=auth.uid() AND c.id=referring_coach_id));
DROP POLICY IF EXISTS live_events_admin_all ON public.live_events; CREATE POLICY live_events_admin_all ON public.live_events FOR ALL USING (public.is_admin(auth.uid())) WITH CHECK (public.is_admin(auth.uid()));
DROP POLICY IF EXISTS live_events_read_upcoming ON public.live_events; CREATE POLICY live_events_read_upcoming ON public.live_events FOR SELECT USING (status IN ('upcoming','active'));
DROP POLICY IF EXISTS live_events_coach_manage ON public.live_events; CREATE POLICY live_events_coach_manage ON public.live_events FOR ALL USING (EXISTS (SELECT 1 FROM public.coaches c JOIN public.profiles p ON p.id=c.profile_id WHERE p.user_id=auth.uid() AND c.id=organizer_coach_id)) WITH CHECK (EXISTS (SELECT 1 FROM public.coaches c JOIN public.profiles p ON p.id=c.profile_id WHERE p.user_id=auth.uid() AND c.id=organizer_coach_id));
DROP POLICY IF EXISTS event_tickets_admin_all ON public.event_tickets; CREATE POLICY event_tickets_admin_all ON public.event_tickets FOR ALL USING (public.is_admin(auth.uid())) WITH CHECK (public.is_admin(auth.uid()));
DROP POLICY IF EXISTS event_tickets_own_read ON public.event_tickets; CREATE POLICY event_tickets_own_read ON public.event_tickets FOR SELECT USING (profile_id IN (SELECT id FROM public.profiles WHERE user_id = auth.uid()));
DROP POLICY IF EXISTS coach_created_courses_admin_all ON public.coach_created_courses; CREATE POLICY coach_created_courses_admin_all ON public.coach_created_courses FOR ALL USING (public.is_admin(auth.uid())) WITH CHECK (public.is_admin(auth.uid()));
DROP POLICY IF EXISTS coach_created_courses_public_read ON public.coach_created_courses; CREATE POLICY coach_created_courses_public_read ON public.coach_created_courses FOR SELECT USING (status = 'active' AND approved_by_admin = TRUE);
DROP POLICY IF EXISTS course_teacher_commissions_admin_all ON public.course_teacher_commissions; CREATE POLICY course_teacher_commissions_admin_all ON public.course_teacher_commissions FOR ALL USING (public.is_admin(auth.uid())) WITH CHECK (public.is_admin(auth.uid()));
DROP POLICY IF EXISTS course_teacher_commissions_own_read ON public.course_teacher_commissions; CREATE POLICY course_teacher_commissions_own_read ON public.course_teacher_commissions FOR SELECT USING (teacher_profile_id IN (SELECT id FROM public.profiles WHERE user_id = auth.uid()) OR public.is_admin(auth.uid()));

CREATE OR REPLACE VIEW public.product_commission_preview AS SELECT p.id,p.name,p.product_type,p.price,p.app_fee,p.nutritionist_fee,p.tax_percentage,p.pix_fee_percentage,p.credit_fee_percentage,p.debit_fee_percentage,ROUND(p.price*p.pix_fee_percentage/100,2) AS pix_gateway_fee,ROUND((p.price-p.app_fee-COALESCE(p.nutritionist_fee,0)-(p.price*p.pix_fee_percentage/100))*p.tax_percentage/100,2) AS pix_tax,ROUND(p.price-p.app_fee-COALESCE(p.nutritionist_fee,0)-(p.price*p.pix_fee_percentage/100)-((p.price-p.app_fee-COALESCE(p.nutritionist_fee,0)-(p.price*p.pix_fee_percentage/100))*p.tax_percentage/100),2) AS pix_commission_base,ROUND((p.price-p.app_fee-COALESCE(p.nutritionist_fee,0)-(p.price*p.pix_fee_percentage/100)-((p.price-p.app_fee-COALESCE(p.nutritionist_fee,0)-(p.price*p.pix_fee_percentage/100))*p.tax_percentage/100))*p.commission_coach/100,2) AS pix_coach_commission,ROUND(p.price*p.credit_fee_percentage/100,2) AS credit_gateway_fee,ROUND((p.price-p.app_fee-COALESCE(p.nutritionist_fee,0)-(p.price*p.credit_fee_percentage/100))*p.tax_percentage/100,2) AS credit_tax,ROUND((p.price-p.app_fee-COALESCE(p.nutritionist_fee,0)-(p.price*p.credit_fee_percentage/100)-((p.price-p.app_fee-COALESCE(p.nutritionist_fee,0)-(p.price*p.credit_fee_percentage/100))*p.tax_percentage/100))*p.commission_coach/100,2) AS credit_coach_commission,p.commission_coach,p.commission_level1,p.commission_level2,p.commission_level3 FROM public.products p WHERE p.status='active' AND p.price IS NOT NULL AND p.price>0;
INSERT INTO public.app_settings (key,value,description) VALUES ('student_nav_order','home,challenge,group,store,courses,benefits,profile','Ordem dos itens no menu inferior do aluno'),('student_home_layout','default','Layout padrão da home do aluno'),('student_store_layout','catalog','Layout padrão da loja do aluno'),('student_benefits_layout','tabs','Layout padrão da aba benefícios'),('product_default_app_fee','20','Taxa app padrão'),('product_default_pix_fee','1.00','Taxa PIX padrão'),('product_default_debit_fee','1.69','Taxa débito padrão'),('product_default_credit_fee','2.99','Taxa crédito padrão'),('product_default_tax','6.00','Imposto padrão'),('product_default_max_installments','12','Parcelas máximas padrão'),('master_coach_default_commission','10.00','Comissão padrão de Master Coach'),('master_coach_requires_approval','true','Exige aprovação de Master Coach'),('room_first_rental_commission','50.00','Comissão do primeiro aluguel de sala'),('coach_required_course','Formação de Coach FitMind — Nível 1','Curso obrigatório para virar coach'),('coach_course_completion_required','true','Exige concluir curso antes de criar conta coach'),('certified_teacher_commission','30.00','Comissão de professores certificados'),('live_event_organizer_percentage','60.00','Percentual do organizador em aulões'),('live_event_platform_percentage','20.00','Percentual da plataforma em aulões'),('live_event_mlm_percentage','20.00','Percentual da rede em aulões') ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value,description=EXCLUDED.description,updated_at=now();
CREATE INDEX IF NOT EXISTS idx_products_product_type ON public.products(product_type); CREATE INDEX IF NOT EXISTS idx_live_events_status_date ON public.live_events(status,event_date); CREATE INDEX IF NOT EXISTS idx_event_tickets_profile ON public.event_tickets(profile_id); CREATE INDEX IF NOT EXISTS idx_room_rentals_profile ON public.room_rentals(renter_profile_id);